class transicionActions extends sfActions
{
  public function executeIndex()
  {
    return $this->forward('transicion', 'list');
  }

  public function executeList()
  {
    $this->wf_transicions = WfTransicionPeer::doSelect(new Criteria());
  }

  public function executeShow()
  {
    $this->wf_transicion = WfTransicionPeer::retrieveByPk($this->getRequestParameter('wf_transicion_id'));
    $this->forward404Unless($this->wf_transicion);
  }

  public function executeCreate()
  {
    $this->wf_transicion = new WfTransicion();

    $this->setTemplate('edit');
  }

  public function executeEdit()
  {
    $this->wf_transicion = WfTransicionPeer::retrieveByPk($this->getRequestParameter('wf_transicion_id'));
    $this->forward404Unless($this->wf_transicion);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('wf_transicion_id'))
    {
      $wf_transicion = new WfTransicion();
    }
    else
    {
      $wf_transicion = WfTransicionPeer::retrieveByPk($this->getRequestParameter('wf_transicion_id'));
      $this->forward404Unless($wf_transicion);
    }

    //$wf_transicion->setWfTransicionId($this->getRequestParameter('wf_transicion_id'));
    $wf_transicion->setDescripcion($this->getRequestParameter('descripcion'));

    $wf_transicion->save();

    return $this->redirect($this->getRequest()->getScriptName().'/transicion/show?wf_transicion_id='.$wf_transicion->getWfTransicionId());
  }

  public function executeDelete()
  {
    $wf_transicion = WfTransicionPeer::retrieveByPk($this->getRequestParameter('wf_transicion_id'));

    $this->forward404Unless($wf_transicion);

    $wf_transicion->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/transicion/list');
  }
}
